const assert = require('node:assert/strict');
const { test } = require('node:test');
const { refundPayment } = require('../../src/payments/refund');

// Fake provider client. No network, no real card, no real money.
function fakeClient({ response, error } = {}) {
  const calls = [];
  return {
    calls,
    refunds: {
      async create(args) {
        calls.push(args);
        if (error) throw error;
        return response;
      },
    },
  };
}

