  const client = fakeClient({ error: new Error('provider unavailable') });
  await assert.rejects(
    refundPayment({ client, paymentId: 'pi_test_2', amount: 1000 }),
    /provider unavailable/
  );
});

test('rejects a non-positive amount before calling the provider', async () => {
  const client = fakeClient({ response: { id: 'should_not_happen' } });
  await assert.rejects(refundPayment({ client, paymentId: 'pi_test_3', amount: 0 }));
  assert.equal(client.calls.length, 0);
});
```

