// In-memory stand-in for the payment provider. Never touches the network.
function createFakePaymentProvider({ payments = {} } = {}) {
  const calls = [];
  return {
    calls,
    async refund({ paymentId, amount }) {
      calls.push({ paymentId, amount });
      const payment = payments[paymentId];
      if (!payment) throw Object.assign(new Error('payment not found'), { code: 'not_found' });
      const refundable = payment.amount - (payment.refunded || 0);
      if (amount > refundable) throw Object.assign(new Error('amount exceeds refundable balance'), { code: 'amount_too_large' });
      payment.refunded = (payment.refunded || 0) + amount;
      return { id: `re_fake_${calls.length}`, paymentId, amount, status: 'succeeded' };
    },
  };
}
module.exports = { createFakePaymentProvider };
```

