// In-memory stand-in for the payment provider. Never makes network calls.
function createFakeProvider() {
  const payments = new Map();   // id -> { amount, refunded }
  const calls = [];
  let nextError = null;

  return {
    calls,
    seedPayment(id, amount) { payments.set(id, { amount, refunded: 0 }); },
    failNextCallWith(err) { nextError = err; },
    async refund({ paymentId, amount }) {
      calls.push({ paymentId, amount });
      if (nextError) { const e = nextError; nextError = null; throw e; }
      const p = payments.get(paymentId);
      if (!p) { const e = new Error('payment not found'); e.code = 'not_found'; throw e; }
      if (p.refunded + amount > p.amount) {
        const e = new Error('refund exceeds payment'); e.code = 'amount_too_large'; throw e;
      }
      p.refunded += amount;
      return { id: `re_fake_${calls.length}`, paymentId, amount, status: 'succeeded' };
    },
  };
}
module.exports = { createFakeProvider };
```

