function createFakeProvider() {
  const calls = [];
  let nextError = null;
  return {
    calls,
    failNextWith(err) { nextError = err; },
    async refund({ paymentId, amountCents }) {
      calls.push({ paymentId, amountCents });
      if (nextError) { const e = nextError; nextError = null; throw e; }
      return { id: `re_fake_${calls.length}`, paymentId, amountCents, status: 'succeeded' };
    },
  };
}
module.exports = { createFakeProvider };
